def max_pair_product(numbers):
    if len(numbers) < 2:
        raise ValueError('Need at least two numbers.')

    # Sort the list in reverse order.
    numbers.sort(reverse=True)

    # Check if the largest number is a negative.
    if numbers[0] < 0:
        # If the second largest number is also negative, then 
        # the maximum product will be the product of the two largest numbers.
        if numbers[1] < 0:
            return (numbers[0] * numbers[1], (numbers[0], numbers[1]))
        # Otherwise, it is the product of the two smallest numbers.
        else:
            return (numbers[0] * numbers[2], (numbers[0], numbers[2]))
    # If the largest number is not negative, the maximum product 
    # is the product of the two largest numbers.
    else:
        return (numbers[0] * numbers[1], (numbers[0], numbers[1]))

