    elif applicant.personal_statement == 'medium quality':
        score += 1.0

    # For parenting degree of the parents (especially PhD level), candidates
    # with strong skills in parent-child interactions should get bonus points
    parenting_skills = ['child development', 'early education', 'parenting techniques']
    skill_matches = [skill for skill in applicant.skills if skill in parenting_skills]
    if len(skill_matches) >= 2 and applicant.parents_degree == 'PhD':
        score += 1.0
    elif len(skill_matches) >= 1 and applicant.parents_degree in ['bachelor', 'master']:
        score += 0.5

    # Also, candidates from low income families have lower scores by default
    if applicant.parents_income == 'low':
        score -= 0.5

    return max(score, 0) # score should not be negative

